178	    };
179	
180	    const detail: DailyDetail = { total: 0, byTeam: {} };
181	    
182	    if (data) {
183	        for (const record of (data as any[])) {
184	            const { team_id, team_name, generation, count } = record;
185	            if (!team_id || !team_name || count === null) continue;
186	            
187	            if (!detail.byTeam[team_id]) {
188	                detail.byTeam[team_id] = { name: team_name, total: 0, byGeneration: {} };
189	            }
190	            
191	            detail.total += count;
192	            detail.byTeam[team_id].total += count;
193	            detail.byTeam[team_id].byGeneration[generation] = count;
194	        }
195	    }
196	    
197	    return detail;
198	}
